    mappings = {2: 2, 3: 3, 4: 4, 10: 10, 11: 11, 12: 12, 13: 13, 17: 3, 18: 3, 26: 26, 28: 28, 31: 31} if self.side == 'left' else {41: 2, 42: 3, 43: 4, 49: 10, 50: 11, 51: 12, 52: 13, 53: 3, 54: 3, 58: 26, 60: 28, 63: 31}
    for old, new in mappings.items():
        data[source == old] = new
    for old, new in ((14, 4), (24, 4), (77, 2), (72, 4)):
